<?php

namespace App\Support;

use Illuminate\Support\Facades\Storage;

/**
 * Above-the-fold CSS inlined into the homepage <head>, generated by
 * `php artisan rgu:build-css`.
 *
 * The file is written with document-relative url("./assets/...") paths; once
 * inlined they must point at the public storage URL instead.
 */
class CriticalCss
{
    public const PATH = 'assets/css/critical.css';

    public function inline(): string
    {
        $css = Storage::disk('public')->get(self::PATH) ?? '';

        return preg_replace(
            '#url\((["\']?)\./assets/#i',
            'url($1'.asset('storage/assets').'/',
            $css
        );
    }
}
